// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AiUsageLog) predicate.AiUsageLog {
	return predicate.AiUsageLog(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AiUsageLog) predicate.AiUsageLog {
	return predicate.AiUsageLog(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AiUsageLog) predicate.AiUsageLog {
	return predicate.AiUsageLog(sql.NotPredicates(p))
}
